  check("the new chests only hold real things", ["delve3", "delve6", "buried", "islet"].every(t => L.TABLES[t] && L.TABLES[t].items.concat(L.TABLES[t].sure || []).every(x => !!K[x[0]])) && L.TABLES.wreck.items.some(x => x[0] === "mapscrap"));
